/**
 * A one-time function to seed the fallback questions into Firestore.
 * This should be executed from a trusted server environment or a secure admin panel.
 * It is idempotent, meaning it won't create duplicate questions if run multiple times.
 */
export async function seedFallbackQuestions() {
    if (!db) {
        console.error("Firestore DB is not initialized. Cannot seed questions.");
        return { success: false, error: "Firestore not initialized." };
    }

    const { writeBatch, collection, doc } = await import('firebase/firestore');
    
    console.log(`Starting to seed ${allFallbackQuestions.length} fallback questions...`);
    
    // Firestore allows a maximum of 500 operations in a single batch.
    const BATCH_SIZE = 499;
    let batch = writeBatch(db);
    let count = 0;
    let totalCount = 0;

    for (const q of allFallbackQuestions) {
        // Create a simple, consistent ID based on the question text
        const docId = (q.question + q.format).toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 50) + Math.random().toString(16).slice(2);
        const docRef = doc(collection(db, 'fallback_questions'), docId);
        
        const questionData: Omit<QuizQuestion, 'id'> & { format: string } = {
            question: q.question,
            options: q.options,
            correctAnswer: q.correctAnswer,
            explanation: q.explanation,
            format: q.format.toLowerCase(),
        };

        // Use 'set' with merge:true to be idempotent. It creates or overwrites.
        batch.set(docRef, { ...questionData, id: docId });
        count++;
        totalCount++;

        if (count === BATCH_SIZE) {
            console.log(`Committing batch of ${count} questions...`);
            await batch.commit();
            // Start a new batch
            batch = writeBatch(db);
            count = 0;
        }
    }

    // Commit the final batch if it has any operations
    if (count > 0) {
        console.log(`Committing final batch of ${count} questions...`);
        await batch.commit();
    }

    console.log(`Successfully seeded ${totalCount} questions into 'fallback_questions' collection.`);
    return { success: true, count: totalCount };
}
